func (writer *StandbySnapshot) String() string {
    var builder strings.Builder
    builder.WriteString("{\"Name\": \"StandbySnapshot\", ")
    builder.WriteString(fmt.Sprintf("\"sbeTemplateId\": %d", writer.SbeTemplateId()))
    builder.WriteString(", ")

    builder.WriteString(`"correlationId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.CorrelationId()))

    builder.WriteString(", ")
    builder.WriteString(`"version": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.Version()))

    builder.WriteString(", ")
    builder.WriteString(`"responseStreamId": `)
    builder.WriteString(fmt.Sprintf(`"%v"`, writer.ResponseStreamId()))

    builder.WriteString(", ")
    {
        atLeastOne := false
        builder.WriteString(`"snapshots": [`)
        writer.Snapshots().ForEach(
            func(value *StandbySnapshotSnapshots) {
                if atLeastOne {
                    builder.WriteString(", ")
                }
                atLeastOne = true
                builder.WriteString(value.String())
            })
        builder.WriteString("]")
    }

    builder.WriteString(", ")
    builder.WriteString(`"responseChannel": `)
    builder.WriteString(`"` + writer.GetResponseChannelAsJsonEscapedString() + `"`);

    builder.WriteString(", ")
    builder.WriteString(`"encodedCredentials": `)
    builder.WriteString(`"`)
        writer.SkipEncodedCredentials()
    builder.WriteString(" bytes of raw data")
    builder.WriteString("}")

    return builder.String()
}

func (m *StandbySnapshot) Skip() {
    for SnapshotsGroup := m.Snapshots(); SnapshotsGroup.HasNext(); {
        SnapshotsGroup.Next().Skip()
    }
    m.SkipResponseChannel()
    m.SkipEncodedCredentials()
}

