func (m *StandbySnapshot) ComputeLength(
    SnapshotsItemLengths []struct{ ArchiveEndpointLength int},
     ResponseChannelLength int,
     EncodedCredentialsLength int) (int, error) {
    length := uint64(m.SbeBlockLength())

    length += m.Snapshots().SbeHeaderSize()
    if (len(SnapshotsItemLengths) > 65534) {
        panic("len(SnapshotsItemLengths) outside of allowed range [E110]")
    }

    for _, e := range SnapshotsItemLengths {
        l, err := m.Snapshots().ComputeLength(e.ArchiveEndpointLength)
        if err != nil {
            return 0, err
        }
        length += uint64(l)
    }

    length += m.ResponseChannelHeaderLength()
    if m.ResponseChannelLength() > 1073741824 {
        return 0, fmt.Errorf("ResponseChannelLength too long for length type [E109]")
    }
    length += uint64(m.ResponseChannelLength())

    length += m.EncodedCredentialsHeaderLength()
    if m.EncodedCredentialsLength() > 1073741824 {
        return 0, fmt.Errorf("EncodedCredentialsLength too long for length type [E109]")
    }
    length += uint64(m.EncodedCredentialsLength())

    return int(length), nil
}
